-- =====================================================================
-- Coca-Cola Event Intelligence  |  schema.sql  |  PostgreSQL 13+
-- Orden de ejecución: schema.sql -> views.sql -> seed.sql
-- IDs: BIGINT GENERATED BY DEFAULT AS IDENTITY (compatible con
--      @GeneratedValue(strategy = GenerationType.IDENTITY) de JPA).
-- Enums: VARCHAR + CHECK (compatible con @Enumerated(EnumType.STRING)).
-- Fechas/hora: TIMESTAMPTZ (OffsetDateTime / Instant en Java).
-- Borrados: RESTRICT por defecto para conservar historia; CASCADE solo en
--           tablas de configuración del evento (activities, event_products).
-- =====================================================================

BEGIN;

DROP TABLE IF EXISTS conversions          CASCADE;
DROP TABLE IF EXISTS surveys              CASCADE;
DROP TABLE IF EXISTS product_interactions CASCADE;
DROP TABLE IF EXISTS interactions         CASCADE;
DROP TABLE IF EXISTS attendances          CASCADE;
DROP TABLE IF EXISTS activities           CASCADE;
DROP TABLE IF EXISTS event_products       CASCADE;
DROP TABLE IF EXISTS products             CASCADE;
DROP TABLE IF EXISTS participants         CASCADE;
DROP TABLE IF EXISTS events               CASCADE;
DROP TABLE IF EXISTS campaigns            CASCADE;
DROP FUNCTION IF EXISTS set_updated_at()  CASCADE;

-- Trigger genérico para updated_at
CREATE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------
-- campaigns
-- ---------------------------------------------------------------------
CREATE TABLE campaigns (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(150) NOT NULL,
    description TEXT,
    start_date  DATE,
    end_date    DATE,
    budget      NUMERIC(14,2),
    status      VARCHAR(20)  NOT NULL DEFAULT 'PLANNED',
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_campaigns_name   UNIQUE (name),
    CONSTRAINT ck_campaigns_status CHECK (status IN ('PLANNED','ACTIVE','COMPLETED','CANCELLED')),
    CONSTRAINT ck_campaigns_dates  CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date),
    CONSTRAINT ck_campaigns_budget CHECK (budget IS NULL OR budget >= 0)
);

-- ---------------------------------------------------------------------
-- events
-- ---------------------------------------------------------------------
CREATE TABLE events (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    campaign_id           BIGINT       REFERENCES campaigns(id) ON DELETE RESTRICT,
    name                  VARCHAR(200) NOT NULL,
    type                  VARCHAR(50)  NOT NULL,   -- libre: SAMPLING, ACTIVATION, FESTIVAL, SPONSORSHIP...
    event_date            DATE         NOT NULL,
    location              VARCHAR(200) NOT NULL,
    description           TEXT,
    objective             TEXT,
    budget                NUMERIC(14,2),
    expected_participants INTEGER,
    responsible           VARCHAR(150),
    status                VARCHAR(20)  NOT NULL DEFAULT 'PLANNED',
    created_at            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT ck_events_status   CHECK (status IN ('PLANNED','ACTIVE','COMPLETED','CANCELLED')),
    CONSTRAINT ck_events_budget   CHECK (budget IS NULL OR budget >= 0),
    CONSTRAINT ck_events_expected CHECK (expected_participants IS NULL OR expected_participants >= 0)
);
CREATE INDEX idx_events_campaign_id ON events(campaign_id);
CREATE INDEX idx_events_event_date  ON events(event_date);
CREATE INDEX idx_events_status      ON events(status);

-- ---------------------------------------------------------------------
-- participants  (sin is_new / is_recurrent: se calcula en vw_participant_event_history)
-- ---------------------------------------------------------------------
CREATE TABLE participants (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    first_name            VARCHAR(100) NOT NULL,
    last_name             VARCHAR(100) NOT NULL,
    phone                 VARCHAR(30),
    email                 VARCHAR(255),
    city                  VARCHAR(100),
    age_range             VARCHAR(10),
    product_preference    VARCHAR(100),
    communication_consent BOOLEAN      NOT NULL DEFAULT FALSE,
    consent_at            TIMESTAMPTZ,
    registration_source   VARCHAR(20)  NOT NULL DEFAULT 'WEB',
    created_at            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT ck_participants_contact  CHECK (email IS NOT NULL OR phone IS NOT NULL),
    CONSTRAINT ck_participants_age      CHECK (age_range IS NULL OR age_range IN ('<18','18-24','25-34','35-44','45-54','55+')),
    CONSTRAINT ck_participants_source   CHECK (registration_source IN ('WEB','QR','ONSITE','SOCIAL','IMPORT','OTHER')),
    CONSTRAINT ck_participants_consent  CHECK (communication_consent = FALSE OR consent_at IS NOT NULL)
);
-- Identidad: un mismo email / teléfono = una misma persona (permite detectar recurrencia)
CREATE UNIQUE INDEX uq_participants_email ON participants (lower(email)) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX uq_participants_phone ON participants (phone)        WHERE phone IS NOT NULL;
CREATE INDEX idx_participants_city ON participants(city);

-- ---------------------------------------------------------------------
-- products + event_products
-- ---------------------------------------------------------------------
CREATE TABLE products (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         VARCHAR(150) NOT NULL,
    category     VARCHAR(80)  NOT NULL,
    flavor       VARCHAR(80),
    presentation VARCHAR(80),
    status       VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE',
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_products_name_presentation UNIQUE (name, presentation),
    CONSTRAINT ck_products_status CHECK (status IN ('ACTIVE','INACTIVE','DISCONTINUED'))
);
CREATE INDEX idx_products_category ON products(category);

CREATE TABLE event_products (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_id   BIGINT      NOT NULL REFERENCES events(id)   ON DELETE CASCADE,
    product_id BIGINT      NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_event_products UNIQUE (event_id, product_id)
);
CREATE INDEX idx_event_products_product_id ON event_products(product_id);

-- ---------------------------------------------------------------------
-- activities
-- ---------------------------------------------------------------------
CREATE TABLE activities (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_id    BIGINT       NOT NULL REFERENCES events(id) ON DELETE CASCADE,
    name        VARCHAR(150) NOT NULL,
    type        VARCHAR(20)  NOT NULL,
    description TEXT,
    start_at    TIMESTAMPTZ,
    end_at      TIMESTAMPTZ,
    status      VARCHAR(20)  NOT NULL DEFAULT 'PLANNED',
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_activities_id_event   UNIQUE (id, event_id),      -- destino de FK compuestas
    CONSTRAINT uq_activities_event_name UNIQUE (event_id, name),
    CONSTRAINT ck_activities_type   CHECK (type IN ('GAME','DYNAMIC','TASTING','ACTIVATION','SURVEY','PROMOTION')),
    CONSTRAINT ck_activities_status CHECK (status IN ('PLANNED','ACTIVE','COMPLETED','CANCELLED')),
    CONSTRAINT ck_activities_dates  CHECK (end_at IS NULL OR start_at IS NULL OR end_at >= start_at)
);
CREATE INDEX idx_activities_event_id ON activities(event_id);

-- ---------------------------------------------------------------------
-- attendances: registro + check-in en una sola fila (reemplaza participant_events)
-- ---------------------------------------------------------------------
CREATE TABLE attendances (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_id        BIGINT      NOT NULL REFERENCES events(id)       ON DELETE RESTRICT,
    participant_id  BIGINT      NOT NULL REFERENCES participants(id) ON DELETE RESTRICT,
    status          VARCHAR(20) NOT NULL DEFAULT 'REGISTERED',
    registered_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    check_in_at     TIMESTAMPTZ,
    check_in_method VARCHAR(20),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- Un participante, un registro/check-in por evento
    CONSTRAINT uq_attendances_event_participant UNIQUE (event_id, participant_id),
    CONSTRAINT ck_attendances_status CHECK (status IN ('REGISTERED','CHECKED_IN','NO_SHOW','CANCELLED')),
    CONSTRAINT ck_attendances_method CHECK (check_in_method IS NULL OR check_in_method IN ('QR','MANUAL')),
    CONSTRAINT ck_attendances_checkin CHECK (
        (status = 'CHECKED_IN' AND check_in_at IS NOT NULL AND check_in_method IS NOT NULL)
     OR (status <> 'CHECKED_IN' AND check_in_at IS NULL AND check_in_method IS NULL)
    )
);
CREATE INDEX idx_attendances_participant_id ON attendances(participant_id);
CREATE INDEX idx_attendances_event_status   ON attendances(event_id, status);

-- ---------------------------------------------------------------------
-- interactions: participante <-> actividad
-- FK compuestas garantizan que el participante esté registrado en ESE evento
-- y que la actividad pertenezca a ESE evento.
-- ---------------------------------------------------------------------
CREATE TABLE interactions (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_id       BIGINT      NOT NULL,
    participant_id BIGINT      NOT NULL,
    activity_id    BIGINT      NOT NULL,
    interacted_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    notes          TEXT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_interactions_attendance FOREIGN KEY (event_id, participant_id)
        REFERENCES attendances (event_id, participant_id) ON DELETE RESTRICT,
    CONSTRAINT fk_interactions_activity FOREIGN KEY (activity_id, event_id)
        REFERENCES activities (id, event_id) ON DELETE RESTRICT
);
CREATE INDEX idx_interactions_event_id       ON interactions(event_id);
CREATE INDEX idx_interactions_activity_id    ON interactions(activity_id);
CREATE INDEX idx_interactions_participant_id ON interactions(participant_id);

-- ---------------------------------------------------------------------
-- product_interactions
-- ---------------------------------------------------------------------
CREATE TABLE product_interactions (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_id        BIGINT      NOT NULL,
    participant_id  BIGINT      NOT NULL,
    product_id      BIGINT      NOT NULL,
    activity_id     BIGINT,                          -- opcional
    tried           BOOLEAN     NOT NULL DEFAULT TRUE,
    rating          SMALLINT,
    purchase_intent VARCHAR(10),
    comment         TEXT,
    interacted_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_product_interactions UNIQUE (event_id, participant_id, product_id),
    CONSTRAINT ck_pi_rating CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
    CONSTRAINT ck_pi_intent CHECK (purchase_intent IS NULL OR purchase_intent IN ('LOW','MEDIUM','HIGH')),
    CONSTRAINT fk_pi_attendance FOREIGN KEY (event_id, participant_id)
        REFERENCES attendances (event_id, participant_id) ON DELETE RESTRICT,
    CONSTRAINT fk_pi_event_product FOREIGN KEY (event_id, product_id)
        REFERENCES event_products (event_id, product_id) ON DELETE RESTRICT,
    -- Si activity_id es NULL la FK compuesta no se evalúa (MATCH SIMPLE)
    CONSTRAINT fk_pi_activity FOREIGN KEY (activity_id, event_id)
        REFERENCES activities (id, event_id) ON DELETE RESTRICT
);
CREATE INDEX idx_pi_product_id     ON product_interactions(product_id);
CREATE INDEX idx_pi_participant_id ON product_interactions(participant_id);
CREATE INDEX idx_pi_activity_id    ON product_interactions(activity_id);

-- ---------------------------------------------------------------------
-- surveys: una encuesta por participante y evento
-- ---------------------------------------------------------------------
CREATE TABLE surveys (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_id             BIGINT      NOT NULL,
    participant_id       BIGINT      NOT NULL,
    organization_score   SMALLINT    NOT NULL,
    service_score        SMALLINT    NOT NULL,   -- atención
    experience_score     SMALLINT    NOT NULL,   -- experiencia / dinámica
    product_score        SMALLINT    NOT NULL,   -- evaluación de productos
    overall_satisfaction SMALLINT    NOT NULL,
    nps_score            SMALLINT    NOT NULL,
    comment              TEXT,
    submitted_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_surveys_event_participant UNIQUE (event_id, participant_id),
    CONSTRAINT ck_surveys_org     CHECK (organization_score   BETWEEN 1 AND 5),
    CONSTRAINT ck_surveys_service CHECK (service_score        BETWEEN 1 AND 5),
    CONSTRAINT ck_surveys_exp     CHECK (experience_score     BETWEEN 1 AND 5),
    CONSTRAINT ck_surveys_prod    CHECK (product_score        BETWEEN 1 AND 5),
    CONSTRAINT ck_surveys_overall CHECK (overall_satisfaction BETWEEN 1 AND 5),
    CONSTRAINT ck_surveys_nps     CHECK (nps_score            BETWEEN 0 AND 10),
    CONSTRAINT fk_surveys_attendance FOREIGN KEY (event_id, participant_id)
        REFERENCES attendances (event_id, participant_id) ON DELETE RESTRICT
);

-- ---------------------------------------------------------------------
-- conversions
-- ---------------------------------------------------------------------
CREATE TABLE conversions (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_id        BIGINT       NOT NULL,
    participant_id  BIGINT       NOT NULL,
    conversion_type VARCHAR(30)  NOT NULL,
    converted_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    description     VARCHAR(500),
    metadata        JSONB,       -- ej. {"coupon_code":"CC-VERANO-10","discount_pct":10}
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT ck_conversions_type CHECK (conversion_type IN
        ('CUPON_REDEEMED','BENEFIT_REDEEMED','FORM_COMPLETED','PROMOTION_ACCEPTED','PURCHASE_INTENT','OTHER')),
    CONSTRAINT fk_conversions_attendance FOREIGN KEY (event_id, participant_id)
        REFERENCES attendances (event_id, participant_id) ON DELETE RESTRICT
);
CREATE INDEX idx_conversions_event_id       ON conversions(event_id);
CREATE INDEX idx_conversions_participant_id ON conversions(participant_id);
CREATE INDEX idx_conversions_type           ON conversions(conversion_type);

-- ---------------------------------------------------------------------
-- Triggers updated_at
-- ---------------------------------------------------------------------
CREATE TRIGGER trg_campaigns_updated    BEFORE UPDATE ON campaigns    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_events_updated       BEFORE UPDATE ON events       FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_participants_updated BEFORE UPDATE ON participants FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_products_updated     BEFORE UPDATE ON products     FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_activities_updated   BEFORE UPDATE ON activities   FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_attendances_updated  BEFORE UPDATE ON attendances  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

COMMIT;
